import{_ as o,o as i,c as a,a2 as r}from"./chunks/framework.BN2sqjC1.js";const v=JSON.parse('{"title":"ADR-0046 — Bootstrap quando il server è tornato indietro (ripristino PITR): ripubblicare, non cancellare","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0046-bootstrap-server-indietro.md","filePath":"adr/0046-bootstrap-server-indietro.md"}'),t={name:"adr/0046-bootstrap-server-indietro.md"};function n(l,e,s,c,d,p){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-0046-—-bootstrap-quando-il-server-e-tornato-indietro-ripristino-pitr-ripubblicare-non-cancellare" tabindex="-1">ADR-0046 — Bootstrap quando il server è tornato indietro (ripristino PITR): ripubblicare, non cancellare <a class="header-anchor" href="#adr-0046-—-bootstrap-quando-il-server-e-tornato-indietro-ripristino-pitr-ripubblicare-non-cancellare" aria-label="Permalink to &quot;ADR-0046 — Bootstrap quando il server è tornato indietro (ripristino PITR): ripubblicare, non cancellare&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Data</strong></td><td>2026-11-02</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§3.4.4 B (bootstrap dal manifest), Appendice A (affidabilità dei dati, RPO); D-04 (nessuna perdita silenziosa); integra ADR-0022 (bug 3) e ADR-0039</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì (§3.4.4: i file che il server non elenca più finiscono nel cestino locale) → richiede aggiornamento di <code>Specifications.md</code> da parte dell&#39;owner</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>ADR-0022 (bug 3) ha fatto rispondere <code>GET /vaults/{id}/changes</code> con <code>410 CURSOR_EXPIRED</code> anche quando il cursore del client è <strong>più avanti</strong> dell&#39;ultimo <code>seq</code> del server: succede dopo un ripristino point-in-time del database cloud, quando i nuovi commit riuserebbero numeri di sequenza già consumati. Il problem distingue i due casi con un campo esteso: <code>compaction_seq</code> per un cursore più vecchio della finestra del changelog (ADR-0038), <code>last_seq</code> per un cursore oltre la fine (<code>services/cloud/internal/sync/changes.go</code>).</p><p>Il client però reagisce allo stesso modo in entrambi i casi (<code>apps/desktop/internal/sync/pull.go</code>, <code>bootstrap</code>): tratta l&#39;albero del server come autorevole. Nel caso del ripristino questo distrugge proprio ciò che il server ha perso:</p><ul><li>un file che tutti i dispositivi hanno alla revisione 5, mentre il server ripristinato è alla 3, viene riscritto con il contenuto della 3 su ogni dispositivo, senza snapshot nella history (<code>overwriteFromRemote</code> non passa da <code>BeforeOverwrite</code>);</li><li>i file creati dopo il punto di ripristino, che il server non elenca più, finiscono nel cestino locale e non vengono mai ricaricati;</li><li>le righe con modifiche locali restano bloccate: il candidato alla revisione 3 viene scartato e la push con <code>base_rev</code> 5 va in conflitto all&#39;infinito.</li></ul><p>Il risultato è una perdita silenziosa su tutti i client, contraria a D-04 e allo spirito di ADR-0022 («ciò che il server ha perso non va distrutto sul client»). La revisione del 2026-11-02 l&#39;ha confermata sul codice (rilievo alto A1).</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><ol><li><strong>Il transport espone i campi estesi del problem.</strong> <code>transport.Problem</code> conserva gli <code>Extra</code> (<code>last_seq</code>, <code>compaction_seq</code>); un helper <code>transport.ServerBehind(err)</code> dice se il 410 riguarda un cursore oltre la fine.</li><li><strong>Bootstrap in modalità <em>reconcile-upload</em>.</strong> Quando il server è indietro, il bootstrap confronta ogni riga locale con l&#39;albero: <ul><li>riga presente sul server con <code>row.ServerRev &gt; rf.Rev</code>, oppure con la stessa revisione ma hash diverso: il contenuto locale è più recente di quello che il server conosce. Non si applica il contenuto remoto; la riga diventa <code>LocalModify</code> con <code>BaseRev = ServerRev = rf.Rev</code> e <code>ServerHash = rf.Hash</code>, così la prossima push la ripubblica come nuova revisione (il merge a tre vie, se un altro dispositivo ha già ripubblicato, resta quello di sempre);</li><li>riga con <code>ServerRev &gt; 0</code> assente dall&#39;albero: il file esisteva sul server prima del ripristino. Invece di <code>applyDelete</code> la riga diventa <code>LocalNew</code> (<code>ServerRev = BaseRev = 0</code>, nuovo <code>op_id</code>), e la push la ricarica; se il file locale non c&#39;è più, la riga viene semplicemente rimossa;</li><li>riga con <code>row.ServerRev &lt; rf.Rev</code> (il server, pur ripristinato, ha qualcosa di più nuovo): si applica come oggi.</li></ul></li><li><strong>Nessuna sovrascrittura senza snapshot.</strong> In ogni bootstrap (anche con <code>compaction_seq</code>), prima di riscrivere un file locale con il contenuto remoto si chiama <code>BeforeOverwrite</code>, come già fa la risoluzione dei conflitti: la versione locale resta recuperabile da <em>File recovery</em>.</li><li>Con <code>compaction_seq</code> (finestra scaduta) il resto del comportamento non cambia: l&#39;albero è autorevole e i file che il server non elenca sono stati cancellati davvero.</li><li>Il cursore viene impostato a <code>tree.as_of_seq</code> come oggi; i file ripubblicati generano nuovi <code>seq</code> sul server ripristinato.</li><li><strong>Un bootstrap interrotto riprende in modalità <em>reconcile-upload</em>.</strong> Finché il bootstrap non salva il cursore, una marca in <code>sync_meta</code> ricorda che il server era indietro: se intanto altri dispositivi hanno ripubblicato e il server non risponde più 410, il bootstrap riparte comunque nella stessa modalità e nessuna riga resta con revisioni che il server non ha più.</li><li><strong>Il cursore riconosce i <code>seq</code> riusati (completamento lato server, M12-W1).</strong> Dopo che un dispositivo ha ripubblicato, <code>last_seq</code> del server ripristinato torna a crescere e riusa numeri già consumati: un dispositivo rimasto offline, con il cursore ora minore o uguale a <code>last_seq</code>, non riceverebbe il 410 e salterebbe in silenzio i cambiamenti riusati. Il client invia quindi con il cursore anche l&#39;identificativo del cambiamento a quel <code>seq</code> (<code>since_id</code>); l&#39;identificativo è quello della riga di <code>file_revisions</code> a quel <code>seq</code>, già una chiave UUID stabile. Il server risponde <code>410 CURSOR_EXPIRED</code> con <code>last_seq</code> quando a quel <code>seq</code> c&#39;è un cambiamento diverso (numero riusato, bootstrap <em>reconcile-upload</em>), e con <code>compaction_seq</code> quando a quel <code>seq</code> non c&#39;è più nessun cambiamento: i commit non lasciano buchi nella sequenza, quindi la riga è stata potata dalla retention e il bootstrap normale è quello sicuro (ripubblicare riporterebbe in vita file cancellati). <code>changes</code> restituisce <code>next_id</code>, <code>tree</code> restituisce <code>as_of_id</code>, e il controllo del cursore e la pagina si leggono nella stessa istantanea. Il parametro è facoltativo, così i client precedenti continuano a funzionare con il comportamento attuale.</li></ol><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Rifiutare il sync e chiedere all&#39;utente</strong> — sicuro ma blocca tutti i dispositivi finché qualcuno non interviene, e non dice cosa fare; la ripubblicazione automatica ottiene lo stesso risultato senza perdite.</li><li><strong>Ricaricare tutto il vault</strong> — semplice ma moltiplica il traffico e crea conflitti artificiali tra dispositivi che hanno lo stesso contenuto; il confronto per revisione ricarica solo ciò che il server ha perso.</li><li><strong>Ripristinare lato server dai blob orfani</strong> — il server non interpreta il contenuto e non conosce i path dei vault privati; solo i client possono ricostruire lo stato.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Dopo un PITR i client ripubblicano le revisioni perse; se più dispositivi avevano la stessa revisione, il primo la ripubblica e gli altri la ritrovano identica (stesso hash, nessun conflitto) oppure vanno al merge.</li><li>Un file cancellato dopo il punto di ripristino può ricomparire su altri dispositivi: è il compromesso scelto, coerente con D-04 (meglio un file in più che uno perso). Il comportamento va descritto nella guida admin (backup e ripristino).</li><li><code>Specifications.md</code> §3.4.4 va aggiornato dall&#39;owner: il cestino locale si applica solo con <code>compaction_seq</code>; il parametro <code>since_id</code> di <code>GET /vaults/{id}/changes</code> va aggiunto a §3.4.4 e all&#39;OpenAPI.</li><li>Nei vault privati l&#39;hash del server è quello del ciphertext: se un altro dispositivo ha già ripubblicato lo stesso testo con un nonce diverso, la riga viene ripubblicata di nuovo come revisione identica, senza conflitti né perdite.</li><li>Test: unitario sul bootstrap con <code>last_seq</code> e test e2e in <code>apps/desktop/internal/sync/e2e_test.go</code> che simula il ripristino del server a un <code>seq</code> precedente.</li></ul>',13)])])}const m=o(t,[["render",n]]);export{v as __pageData,m as default};
